// Minimal re-implementation of Python's argparse behavior for this program.
// Supports: --name value, --name=value, -h/--help, required checks,
// and "unrecognized arguments" errors with exit code 2.

import { basename } from 'node:path';

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog || basename(process.argv[1] || 'program');
    this.arguments = []; // { name, required, metavar }
  }

  add_argument(flag, { type = 'str', required = false } = {}) {
    // flag like '--a'; metavar is the upper-cased dest name (argparse default)
    const dest = flag.replace(/^--?/, '');
    this.arguments.push({ flag, dest, type, required, metavar: dest.toUpperCase() });
  }

  _usageLine() {
    const parts = [`usage: ${this.prog}`, '[-h]'];
    for (const arg of this.arguments) {
      const chunk = `${arg.flag} ${arg.metavar}`;
      parts.push(arg.required ? chunk : `[${chunk}]`);
    }
    return parts.join(' ');
  }

  _error(message) {
    process.stderr.write(this._usageLine() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _printHelp() {
    let out = this._usageLine() + '\n\noptions:\n';
    out += '  -h, --help  show this help message and exit\n';
    for (const arg of this.arguments) {
      out += `  ${arg.flag} ${arg.metavar}\n`;
    }
    process.stdout.write(out);
    process.exit(0);
  }

  parse_args(argv = process.argv.slice(2)) {
    const values = {};
    for (const arg of this.arguments) values[arg.dest] = undefined;

    const byFlag = new Map(this.arguments.map((a) => [a.flag, a]));
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      if (token === '-h' || token === '--help') {
        this._printHelp();
      }

      let flag = token;
      let inlineValue = null;
      if (token.startsWith('--') && token.includes('=')) {
        const eq = token.indexOf('=');
        flag = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      const arg = byFlag.get(flag);
      if (!arg) {
        extras.push(token);
        continue;
      }

      if (inlineValue !== null) {
        values[arg.dest] = inlineValue;
      } else if (i + 1 < argv.length) {
        values[arg.dest] = argv[++i];
      } else {
        this._error(`argument ${arg.flag}: expected one argument`);
      }
    }

    if (extras.length > 0) {
      this._error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const missing = this.arguments
      .filter((a) => a.required && values[a.dest] === undefined)
      .map((a) => a.flag);
    if (missing.length > 0) {
      this._error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return values;
  }
}

