// Re-implementation of whoosh.fields: Schema, TEXT, ID.
// Only the observable behavior needed by the program is modeled.

export class FieldType {
  constructor({ stored = false } = {}) {
    this.stored = stored;
  }
}

export function TEXT(options = {}) {
  return new FieldType(options);
}

export function ID(options = {}) {
  return new FieldType(options);
}

export class Schema {
  constructor(fields = {}) {
    // fields: { name: FieldType }
    this.fields = { ...fields };
  }

  names() {
    return Object.keys(this.fields);
  }
}

