// Re-implementation of whoosh.index: create_in and the Index object.
// Documents are kept in memory and persisted to the given directory on commit.

import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

class IndexWriter {
  constructor(index) {
    this.index = index;
    this.pending = [];
  }

  add_document(fields) {
    this.pending.push({ ...fields });
  }

  commit() {
    this.index.documents.push(...this.pending);
    this.pending = [];
    // Persist a manifest so the on-disk directory mirrors a committed index.
    writeFileSync(
      join(this.index.dirname, 'segments.json'),
      JSON.stringify({ doc_count: this.index.documents.length })
    );
  }
}

class IndexSearcher {
  constructor(index) {
    this.index = index;
  }

  search(query) {
    return this.index.documents.filter((doc) => query.matches(doc));
  }
}

export class Index {
  constructor(dirname, schema) {
    this.dirname = dirname;
    this.schema = schema;
    this.documents = [];
  }

  writer() {
    return new IndexWriter(this);
  }

  searcher() {
    return new IndexSearcher(this);
  }
}

export function create_in(dirname, schema) {
  mkdirSync(dirname, { recursive: true });
  return new Index(dirname, schema);
}

