// Re-implementation of whoosh.qparser: QueryParser.
// The program only imports it; a minimal query-string parser is provided
// for interface parity.

export class QueryParser {
  constructor(fieldname, schema) {
    this.fieldname = fieldname;
    this.schema = schema;
  }

  parse(text) {
    const needle = String(text);
    return {
      matches: (doc) => String(doc[this.fieldname] ?? '').includes(needle),
    };
  }
}

