import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ArgumentParser } from './argparser.mjs';
import { Schema, TEXT, ID } from './fields.mjs';
import { create_in } from './index.mjs';
import { QueryParser } from './qparser.mjs';
import { Every } from './query.mjs';

const parser = new ArgumentParser();
parser.add_argument('--a', { type: 'str', required: true });
parser.add_argument('--b', { type: 'str', required: true });
parser.add_argument('--c', { type: 'str', required: true });
const args = parser.parse_args();

const schema = new Schema({ title: TEXT({ stored: true }), content: TEXT() }); // Create schema
const temp_dir = mkdtempSync(join(tmpdir(), 'test11-')); // Create temp dir
const ix = create_in(temp_dir, schema); // Create index
const writer = ix.writer(); // Create writer
writer.add_document({ title: args.a, content: args.b }); // Add first document
writer.add_document({ title: args.b, content: args.c }); // Add second document
writer.add_document({ title: args.c, content: args.a }); // Add third document
writer.commit(); // Commit
const searcher = ix.searcher(); // Create searcher
const every_query = new Every(); // Create query to match all documents
const results = searcher.search(every_query); // Search all documents
console.log(results.length); // Get total document count

